//! OIDC resource-server auth: Bearer JWT validation against a JWKS.
//!
//! Design §4.2: validates signature, `iss`, `aud`, `exp`/`nbf` (30 s skew),
//! and requires `sub`. For local dev/tests a static JWKS file may be supplied
//! via `OAUTH_JWKS_FILE` (per-developer keys generated by
//! `backend/dev/gen-dev-keys.sh`, never committed); booting with it requires
//! an explicit `I_ACCEPT_DEV_JWKS=1` so accidental static-key trust in real
//! deployments is impossible.

use std::sync::Arc;
use std::time::Duration;

use anyhow::bail;
use jsonwebtoken::jwk::JwkSet;
use jsonwebtoken::{decode, Algorithm, DecodingKey, Validation};
use parking_lot::RwLock;
use serde::Deserialize;

use crate::error::Problem;

/// Minimum interval between JWKS refresh attempts (successful or not).
const REFRESH_COOLDOWN: Duration = Duration::from_secs(60);
/// Bound for the initial fetch: a slow IdP must not delay binding the listener.
const JWKS_CONNECT_TIMEOUT: Duration = Duration::from_secs(3);
const JWKS_REQUEST_TIMEOUT: Duration = Duration::from_secs(5);

/// Claims expected in an access token. `aud` may be string or array.
#[derive(Debug, Deserialize, Clone)]
pub struct Claims {
    pub sub: String,
    // and are not otherwise read; keep them for completeness of the decoded
    // token shape.
    #[allow(dead_code)]
    pub iss: String,
    #[allow(dead_code)]
    pub aud: serde_json::Value,
    #[serde(default)]
    #[allow(dead_code)]
    pub nbf: Option<u64>,
    #[allow(dead_code)]
    pub exp: u64,
    #[allow(dead_code)]
    pub scope: Option<String>,
}

/// One JWK (kid + key) used for signature verification.
#[derive(Clone)]
pub struct VerifiedKey {
    pub kid: String,
    pub key: DecodingKey,
}

#[derive(Clone)]
pub struct AuthConfig {
    pub issuer: String,
    pub audience: String,
    /// kid -> DecodingKey, refreshed from the IdP's `jwks_uri`.
    pub keys: Arc<RwLock<Vec<VerifiedKey>>>,
    /// Live JWKS endpoint; `None` for the static dev file.
    pub jwks_url: Option<String>,
    /// Last refresh *attempt* (rate-limits re-fetches on unknown kid, so a
    /// failing or hanging IdP cannot be hit once per request).
    pub last_refresh: Arc<RwLock<Option<std::time::Instant>>>,
    /// Serializes refreshes: concurrent unknown-kid requests share one fetch.
    pub refresh_lock: Arc<tokio::sync::Mutex<()>>,
    /// Shared client; its timeout bounds every JWKS fetch (connect, headers,
    /// and body).
    pub client: reqwest::Client,
    pub clock_skew: u64,
}

impl AuthConfig {
    /// Builds config from env: `OAUTH_ISSUER_URL`, `OAUTH_AUDIENCE`,
    /// `OAUTH_JWKS_URL` (or `OAUTH_JWKS_FILE` for the static dev JWKS).
    pub async fn from_env() -> anyhow::Result<Self> {
        let issuer = std::env::var("OAUTH_ISSUER_URL")?;
        let audience = std::env::var("OAUTH_AUDIENCE")?;
        let jwks_url = env_nonempty("OAUTH_JWKS_URL");
        let jwks_file = env_nonempty("OAUTH_JWKS_FILE");

        let client = reqwest::Client::builder()
            .connect_timeout(JWKS_CONNECT_TIMEOUT)
            .timeout(JWKS_REQUEST_TIMEOUT)
            .build()?;

        // URL wins over file: prod deployments point at the IdP's live JWKS
        // endpoint, while the static file is the local-dev fallback.
        let mut keys = Vec::new();
        match (&jwks_url, &jwks_file) {
            (Some(url), _) => match fetch_jwks(&client, url).await {
                Ok(jwks) => keys = Self::extract_keys(&jwks)?,
                // Start anyway: the listener must come up even when the IdP is
                // down. `refresh_keys` retries on the first unknown kid.
                Err(e) => {
                    tracing::warn!(error = %e, url = %url, "initial JWKS fetch failed; will retry lazily")
                }
            },
            (None, Some(path)) => {
                if !dev_jwks_accepted(std::env::var("I_ACCEPT_DEV_JWKS").ok().as_deref()) {
                    bail!(
                        "OAUTH_JWKS_FILE is set but I_ACCEPT_DEV_JWKS is not \"1\".\n\
                         A static JWKS file means trust in a key whose private half\n\
                         someone else may hold. Prefer OAUTH_JWKS_URL against your\n\
                         IdP; set I_ACCEPT_DEV_JWKS=1 only if you own the file."
                    );
                }
                let jwks: JwkSet = serde_json::from_reader(std::fs::File::open(path)?)?;
                keys = Self::extract_keys(&jwks)?;
            }
            (None, None) => {}
        }
        Ok(Self {
            issuer,
            audience,
            keys: Arc::new(RwLock::new(keys)),
            jwks_url,
            last_refresh: Arc::new(RwLock::new(None)),
            refresh_lock: Arc::new(tokio::sync::Mutex::new(())),
            client,
            clock_skew: 30,
        })
    }

    /// Refreshes the JWKS from the IdP (at most one attempt per minute, one
    /// attempt in flight); returns the key for `kid` if present afterwards.
    ///
    /// Both bounds apply to failed attempts too: `kid` is attacker-controlled,
    /// so without them every request could open a new connection to the IdP.
    pub async fn refresh_keys(&self, kid: &str) -> Option<VerifiedKey> {
        let url = self.jwks_url.as_ref()?;

        // Another request is already fetching: don't queue up behind it.
        let _guard = self.refresh_lock.try_lock().ok()?;

        let too_soon = {
            let last = self.last_refresh.read();
            match *last {
                Some(t) => t.elapsed() < REFRESH_COOLDOWN,
                None => false,
            }
        };
        if too_soon {
            return None;
        }
        // Stamp the attempt before awaiting: a hanging IdP must not be retried
        // by every subsequent request while this one is still in flight.
        *self.last_refresh.write() = Some(std::time::Instant::now());

        let jwks = match fetch_jwks(&self.client, url).await {
            Ok(jwks) => jwks,
            Err(e) => {
                tracing::warn!(error = %e, url = %url, "JWKS refresh failed");
                return None;
            }
        };
        let keys = match Self::extract_keys(&jwks) {
            Ok(keys) => keys,
            Err(e) => {
                tracing::warn!(error = %e, url = %url, "JWKS refresh produced no usable keys");
                return None;
            }
        };
        *self.keys.write() = keys;
        self.keys.read().iter().find(|k| k.kid == kid).cloned()
    }

    fn extract_keys(jwks: &JwkSet) -> anyhow::Result<Vec<VerifiedKey>> {
        let mut keys = Vec::new();
        for jwk in &jwks.keys {
            let kid = jwk.common.key_id.clone().unwrap_or_default();
            let key = DecodingKey::from_jwk(jwk)?;
            keys.push(VerifiedKey { kid, key });
        }
        Ok(keys)
    }
}

/// Fetches and parses a JWKS over the shared, timeout-bounded client.
async fn fetch_jwks(client: &reqwest::Client, url: &str) -> reqwest::Result<JwkSet> {
    client
        .get(url)
        .send()
        .await?
        .error_for_status()?
        .json()
        .await
}

/// Reads an env var, treating empty strings as unset.
fn env_nonempty(key: &str) -> Option<String> {
    match std::env::var(key) {
        Ok(v) if !v.trim().is_empty() => Some(v),
        _ => None,
    }
}

/// True when the operator has explicitly accepted the dev-JWKS risk: exact
/// value "1" in `I_ACCEPT_DEV_JWKS`.
///
/// The old shared dev key is purged from git; per-developer keys are generated
/// by `backend/dev/gen-dev-keys.sh`. Any static JWKS still names a keypair
/// whose private half someone may hold, so accepting the risk stays opt-in
/// per boot.
fn dev_jwks_accepted(v: Option<&str>) -> bool {
    matches!(v.map(str::trim), Some("1"))
}

/// Validates a bearer token; returns claims or a Problem.
///
/// Unknown kids trigger one rate-limited JWKS refresh (IdP key rotation);
/// static dev-file JWKS never refresh.
pub async fn validate_token(token: &str, cfg: &AuthConfig) -> Result<Claims, Problem> {
    let header = jsonwebtoken::decode_header(token)
        .map_err(|e| Problem::unauthorized(format!("bad header: {e}")))?;
    let kid = header
        .kid
        .clone()
        .ok_or_else(|| Problem::unauthorized("no kid in header"))?;

    let cached = {
        let keys = cfg.keys.read();
        keys.iter().find(|k| k.kid == kid).cloned()
    };
    let key = match cached {
        Some(k) => k,
        None => cfg
            .refresh_keys(&kid)
            .await
            .ok_or_else(|| Problem::unauthorized(format!("unknown kid: {kid}")))?,
    };

    // Pin the algorithm family: RS256/RS384/RS512 only. The header's alg is
    // attacker-controlled; pinning bars the none/type-confusion family at
    // the validator level, independent of key-vs-alg matching.
    let mut validation = Validation::new(Algorithm::RS256);
    validation.algorithms = vec![Algorithm::RS256, Algorithm::RS384, Algorithm::RS512];
    validation.set_issuer(std::slice::from_ref(&cfg.issuer));
    validation.set_audience(std::slice::from_ref(&cfg.audience));
    validation.leeway = cfg.clock_skew;
    validation.validate_exp = true;
    validation.validate_nbf = true;
    decode::<Claims>(token, &key.key, &validation)
        .map(|d| d.claims)
        .map_err(|e| Problem::unauthorized(format!("{e}")))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn dev_jwks_guard_requires_explicit_acceptance() {
        assert!(dev_jwks_accepted(Some("1")));
        assert!(dev_jwks_accepted(Some(" 1")));
        assert!(!dev_jwks_accepted(Some("true")));
        assert!(!dev_jwks_accepted(Some("")));
        assert!(!dev_jwks_accepted(Some("yes")));
        assert!(!dev_jwks_accepted(None));
    }

    /// Accepts connections and never responds, so only the client timeout can
    /// end a fetch. Returns the endpoint and the accept counter.
    async fn hanging_jwks_server() -> (String, Arc<AtomicUsize>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}/jwks", listener.local_addr().unwrap());
        let accepts = Arc::new(AtomicUsize::new(0));
        let counter = accepts.clone();
        tokio::spawn(async move {
            loop {
                let Ok((stream, _)) = listener.accept().await else {
                    return;
                };
                counter.fetch_add(1, Ordering::SeqCst);
                tokio::spawn(async move {
                    let _hold = stream;
                    tokio::time::sleep(Duration::from_secs(30)).await;
                });
            }
        });
        (url, accepts)
    }

    /// Config with an aggressive timeout so the tests stay fast.
    fn config(url: String) -> AuthConfig {
        AuthConfig {
            issuer: "https://idp.example.com".into(),
            audience: "twt-api".into(),
            keys: Arc::new(RwLock::new(Vec::new())),
            jwks_url: Some(url),
            last_refresh: Arc::new(RwLock::new(None)),
            refresh_lock: Arc::new(tokio::sync::Mutex::new(())),
            client: reqwest::Client::builder()
                .timeout(Duration::from_millis(200))
                .build()
                .unwrap(),
            clock_skew: 30,
        }
    }

    #[tokio::test]
    async fn hanging_idp_is_bounded_and_not_retried_per_request() {
        let (url, accepts) = hanging_jwks_server().await;
        let cfg = config(url);

        let started = std::time::Instant::now();
        assert!(cfg.refresh_keys("unknown").await.is_none());
        assert!(
            started.elapsed() < Duration::from_secs(2),
            "refresh must be bounded by the client timeout, took {:?}",
            started.elapsed()
        );

        // Failed attempts count against the cooldown: no second connection.
        let started = std::time::Instant::now();
        assert!(cfg.refresh_keys("unknown").await.is_none());
        assert!(started.elapsed() < Duration::from_millis(50));
        assert_eq!(accepts.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn concurrent_refreshes_share_one_fetch() {
        let (url, accepts) = hanging_jwks_server().await;
        let cfg = config(url);

        let (a, b) = tokio::join!(cfg.refresh_keys("a"), cfg.refresh_keys("b"));
        assert!(a.is_none());
        assert!(b.is_none());
        assert_eq!(accepts.load(Ordering::SeqCst), 1);
    }
}
